package com.ruoyi.medical.persistence;
import com.ruoyi.medical.contracts.*;import java.io.*;import java.util.*;
/** Narrow first implementation: the declared data-policy basis is an actual approved fixed source in an actual snapshot. */
public final class ModelPolicyBasisAuthority {
 public record Evidence(String source_version,String rights_revision,String project_id,String snapshot_id,String parse_version){}
 private final SourceReadAuthority sources;private final String environment,region;
 public ModelPolicyBasisAuthority(SourceReadAuthority sources,String environment,String region){this.sources=Objects.requireNonNull(sources);if(environment==null||environment.isBlank()||region==null||region.isBlank())throw new IllegalArgumentException("Explicit policy-reading environment and region required");this.environment=environment;this.region=region;}
 public final class Verified{private final EnterpriseAccess.Admission admission;private final PermissionProtocol.Basis basis;private final Evidence evidence;private final SourceReadProtocol.VerifiedSource proof;private Verified(EnterpriseAccess.Admission a,PermissionProtocol.Basis basis,Evidence evidence,SourceReadProtocol.VerifiedSource proof){this.admission=a;this.basis=basis;this.evidence=evidence;this.proof=proof;}public List<PermissionProtocol.GrantRow> authorizations(){var list=new ArrayList<PermissionProtocol.GrantRow>();list.add(proof.sourceGrant());if(proof.projectGrant()!=null)list.add(proof.projectGrant());return List.copyOf(list);}public void requireCurrent()throws IOException{if(!proof.equals(require(admission,basis,evidence).proof))throw new TenantAccessException(ErrorCode.SCOPE_STALE);}}
 public Verified require(EnterpriseAccess.Admission a,PermissionProtocol.Basis basis,Evidence evidence)throws IOException{if(!basis.version_id().equals(evidence.source_version()))throw new TenantAccessException(ErrorCode.MODEL_POLICY_INCOMPLETE);var proof=sources.require(a,new SourceReadProtocol.ReadRequirement(evidence.source_version(),evidence.rights_revision(),evidence.project_id(),evidence.snapshot_id(),evidence.parse_version(),null,SourceReadProtocol.Use.FORMAL,"MODEL_ENABLEMENT",environment,region,null));if(!basis.content_sha256().equals(proof.source().originalSha256()))throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);return new Verified(a,basis,evidence,proof);}
}
